#!/usr/bin/env bash
set -euo pipefail
umask 077
VERSION="1.0.0-rc10"
EXPECTED_SHA256="602c4affea481391cdad0eaf2abbd129436314365fa677158407fc7889ba07dc"
usage() {
  cat <<'HADS_NEXT_USAGE'
HADS Next 1.0.0-rc10 — samostatná vývojová aplikace, nikoli produkční RC.
Použití:
  bash HADS_Next_install_1.0.0-rc10.sh --verify
  bash HADS_Next_install_1.0.0-rc10.sh --extract-only /absolutni/novy-adresar
  bash HADS_Next_install_1.0.0-rc10.sh --install-dev
  bash HADS_Next_install_1.0.0-rc10.sh --upgrade
Nová instalace přidá local_hads_next_practical. Výslovný --upgrade aktualizuje ověřený Next RC6 až RC9 přes nativní Supervisor update a zachová /data. Podle zadání nevytváří novou předinstalační HA/OneDrive zálohu. Povinné zálohy před opravami zůstávají. Starý Hermes 2.0.0-rc3 se nemění.
Původní Hermes je součástí balíčku. AI i vlastní testovací opravný katalog vyžadují výslovný souhlas. Obecné produkční zápisy jsou zakázané. Živá HAOS přejímka čeká.
HADS_NEXT_USAGE
}
MODE="${1:-}"
case "$MODE" in
  --help) [ "$#" = 1 ] || exit 2; usage; exit 0 ;;
  --verify|--install-dev|--upgrade|--upgrade-rc6|--upgrade-rc7) [ "$#" = 1 ] || { usage; exit 2; } ;;
  --extract-only) [ "$#" = 2 ] || { usage; exit 2; } ;;
  *) usage; exit 2 ;;
esac
command -v python3 >/dev/null || { echo 'Chybí python3 v terminálové aplikaci. Podrobnosti jsou v návodu DOCS.md.' >&2; exit 1; }
command -v base64 >/dev/null || { echo 'Chybí base64.' >&2; exit 1; }
STAGING="$(mktemp -d /tmp/hads-next-install.XXXXXX)"
cleanup() {
  case "$STAGING" in /tmp/hads-next-install.*) rm -rf -- "$STAGING" ;; esac
}
trap cleanup EXIT
base64 -d > "$STAGING/payload.tar.gz" <<'HADS_NEXT_PAYLOAD'
